# Feature Engineering — Build Master DataFrame:

def clean_html(t):
    if not t: return ''
    return BeautifulSoup(str(t),'html.parser').get_text(' ',strip=True)

def parse_salary(s):
    if not s: return None
    s = str(s)

    # Detect currency
    is_rupee = any(x in s for x in ['₹', 'INR', 'inr', 'Rs.', 'rs.'])
    is_lakh  = 'lakh' in s.lower() or 'lac' in s.lower()

    # Clean and extract numbers
    nums = re.findall(r'\d+\.?\d*', s.replace(',',''))
    vals = [float(n) for n in nums if float(n) > 100]
    if not vals: return None

    # Hourly to annual
    if '/hr' in s.lower() or 'hour' in s.lower():
        vals = [v * 2080 for v in vals]

    # Lakhs to full rupees
    if is_lakh:
        vals = [v * 100000 for v in vals]

    salary = sum(vals[:2]) / min(len(vals[:2]), 2)

    # Convert INR to USD (1 USD = 83 INR)
    if is_rupee or is_lakh:
        salary = salary / 83

    # Remove unrealistic values
    if salary < 5000 or salary > 2000000:
        return None

    return salary


def seniority_from_title(t):
    t = str(t).lower()
    if any(x in t for x in ['director','vp','vice president','head of','chief','cto','cdo']): return 'Director'
    if any(x in t for x in ['senior','sr.','sr','lead','principal','staff','expert']): return 'Senior'
    if any(x in t for x in ['junior','jr','entry','intern','graduate','trainee']): return 'Junior'
    if any(x in t for x in ['manager','supervisor','team lead']): return 'Manager'
    return 'Mid'

def posted_days_ago(s):
    if not s: return None
    s = str(s).lower()
    n = re.search(r'(\d+)', s)
    if not n: return 1
    n = int(n.group(1))
    if 'hour' in s: return 0
    if 'day' in s: return n
    if 'week' in s: return n*7
    if 'month' in s: return n*30
    return n

