# Competition Score:
# Low applicants + easy apply + recent = best opportunity:
def competition_score(row):
    score = 50  # base
    apps = row.get('applicants', 0) or 0
    if apps == 0: score += 10
    elif apps < 50: score += 20
    elif apps < 100: score += 5
    else: score -= 20
    if row.get('easy_apply'): score += 15
    days = row.get('days_ago', 30) or 30
    if days <= 3: score += 15
    elif days <= 7: score += 10
    elif days > 21: score -= 10
    return min(max(score, 0), 100)

df['competition_score'] = df.apply(competition_score, axis=1)
df['opportunity_level'] = pd.cut(df['competition_score'],
    bins=[0,40,60,80,100], labels=['Low','Medium','High','Hot'])

# GTM Company Target Score:
# Rank companies by: total openings + role diversity + seniority + recency:
company_stats = df.groupby('company').agg(
    total_jobs = ('title','count'),
    unique_roles = ('title','nunique'),
    avg_recency = ('days_ago', lambda x: x[x>0].mean() if (x>0).any() else 30),
    has_director = ('seniority', lambda x: int('Director' in x.values)),
    senior_pct = ('seniority', lambda x: (x=='Mid-Senior level').mean()),
    remote_pct = ('remote', 'mean'),
    avg_applicants = ('applicants', lambda x: x[x>0].mean() if (x>0).any() else 0),).reset_index()

# Normalize each factor 0-100:
def norm(s): return ((s-s.min())/(s.max()-s.min())*100).fillna(0)

company_stats['gtm_score'] = (
    norm(company_stats['total_jobs'])   * 0.35 +
    norm(company_stats['unique_roles']) * 0.25 +
    norm(100 - company_stats['avg_recency'].fillna(30)) * 0.20 +
    company_stats['has_director'] * 20 +
    norm(company_stats['senior_pct']) * 0.10).round(1)

company_stats = company_stats.sort_values('gtm_score', ascending=False)

print('TOP GTM TARGET COMPANIES (ranked by buying intent signal)')
