# Salary Predictor — Any Job Description:

def predict_salary(description, seniority='Mid-Senior level', remote=False):
    desc_lower = description.lower()

    # Skills flags based on SKILL_PATTERNS
    skill_flags = {sk: int(bool(re.search(pat, desc_lower))) for sk, pat in SKILL_PATTERNS.items()}
    skill_vals = [skill_flags[sk] for sk in SKILL_PATTERNS.keys()] # Ensure order for X_skills

    txt = tfidf.transform([description])

    # Reconstruct tabular_features in the exact order as in training
    # Use existing kernel variables for mappings and medians

    # 1. seniority_num
    sen_num = seniority_order.get(seniority, 2) # 2 is fillna value for 'Unknown'

    # 2. role_salary_rank (use mean from training data as role_category is not an input)
    role_sal_rank = role_salary.mean()

    # 3. city_salary_rank (use mean from training data as city is not an input)
    city_sal_rank = city_salary.mean()

    # 4. ai_skill_score
    ai_skill_score = sum(skill_flags.get(s, 0) for s in high_value)

    # 5. traditional_score
    traditional_score = sum(skill_flags.get(s, 0) for s in low_value)

    # 6. title_sen_num (derive from seniority input or use default)
    temp_title_seniority_str = seniority_from_title(seniority)
    title_sen_number = title_sen_order.get(temp_title_seniority_str, 1) # 1 is fillna for 'Mid'

    # 7. skills_count
    skills_count = sum(skill_flags.values())

    # 8. remote
    remote_flag = int(remote)

    # 9. easy_apply (not derivable, use a default like 0)
    easy_apply_flag = 0

    # 10. competition_score
    comp_score = 60  # default

    # 11. desc_length
    desc_length = len(description) / 10000

    # 12. benefits_score (not derivable, use a default like 0)
    benefits_score = 0

    # Create the tabular features array in the exact order of tabular_features
    current_tabular_features = [
        sen_num,
        role_sal_rank,
        city_sal_rank,
        ai_skill_score,
        traditional_score,
        title_sen_number,
        skills_count,
        remote_flag,
        easy_apply_flag,
        comp_score,
        desc_length,
        benefits_score
    ]

    X_skills = csr_matrix([skill_vals])
    X_tab = csr_matrix([current_tabular_features])

    X_p = hstack([txt, X_skills, X_tab])

    pred = model.predict(X_p)[0]
    detected = [sk for sk,v in skill_flags.items() if v] # Use skill_flags dict to preserve original keys for detected list
    return pred, detected

