import anthropic, json
client = anthropic.Anthropic(api_key=os.environ.get('ANTHROPIC_API_KEY'))

def execute_tool(name, params):
    if name == 'analyze_city':
        city = params['city']
        subset = df[df['city'].str.lower()==city.lower()]
        sal_sub = subset.dropna(subset=['salary'])
        return {
            'city': city,
            'total_jobs': len(subset),
            'median_salary': int(sal_sub['salary'].median()) if len(sal_sub)>0 else 0,
            'top_companies': subset['company'].value_counts().head(3).to_dict(),
        }
    elif name == 'analyze_skill':
        sk = params['skill'].lower()
        if sk not in df.columns:
            return {'error': f'Skill {sk} not found'}
        sal_sub = df.dropna(subset=['salary'])
        w  = sal_sub[sal_sub[sk]==1]['salary']
        wo = sal_sub[sal_sub[sk]==0]['salary']
        return {
            'skill': sk,
            'demand_pct': round(df[sk].mean()*100,1),
            'salary_premium': int(w.median()-wo.median()) if len(w)>0 and len(wo)>0 else 0,
        }
    elif name == 'get_top_gtm_targets':
        n = params.get('top_n', 5)
        top = company_stats.head(n)[['company','total_jobs','gtm_score']]
        return top.to_dict('records')
    elif name == 'find_hot_opportunities':
        min_s = params.get('min_score', 80)
        hot = df[df['competition_score']>=min_s][['title','company','competition_score']].head(5)
        return hot.to_dict('records')
    return {'error': 'Unknown tool'}

TOOLS = [
    {'name':'analyze_city',
     'description':'Get salary and job data for a city',
     'input_schema':{'type':'object','properties':{'city':{'type':'string'}},'required':['city']}},
    {'name':'analyze_skill',
     'description':'Get salary premium for a skill',
     'input_schema':{'type':'object','properties':{'skill':{'type':'string'}},'required':['skill']}},
    {'name':'get_top_gtm_targets',
     'description':'Get top GTM target companies',
     'input_schema':{'type':'object','properties':{'top_n':{'type':'integer'}},'required':['top_n']}},
    {'name':'find_hot_opportunities',
     'description':'Find hottest job opportunities',
     'input_schema':{'type':'object','properties':{'min_score':{'type':'integer'}},'required':['min_score']}},
]

print('CLAUDE AGENTIC LOOP')

messages = [{'role':'user','content':f"""You are a talent intelligence analyst.
Data: {len(df):,} LinkedIn jobs via Bright Data, USA.
Make exactly 4 tool calls — one per task:
1. analyze_city for San Francisco
2. analyze_skill for llm_genai
3. get_top_gtm_targets with top_n=5
4. find_hot_opportunities with min_score=80
Then write a short GTM intelligence report."""}]

tool_calls_made = 0

for iteration in range(10):
    response = client.messages.create(
        model='claude-sonnet-4-6',
        max_tokens=2000,
        tools=TOOLS,
        messages=messages
    )

    if response.stop_reason == 'end_turn':
        texts = [b.text for b in response.content if hasattr(b,'text') and b.text]
        AGENT_REPORT = texts[0] if texts else "Analysis complete"
        print(f'\n Done! Tool calls made: {tool_calls_made}')
        break

    tool_results = []
    for block in response.content:
        if block.type == 'tool_use':
            tool_calls_made += 1
            result = execute_tool(block.name, block.input)
            print(f' {block.name} → done')
            tool_results.append({
                'type': 'tool_result',
                'tool_use_id': block.id,
                'content': json.dumps(result)
            })

    if tool_results:
        messages.append({'role':'assistant','content':response.content})
        messages.append({'role':'user','content':tool_results})

print('\n AGENT REPORT:')
print(AGENT_REPORT)

